/************************************************************\
 **  pll_m4_hdmi.v
 **  M2 milestone PLL (identical to the M1 PLL): 50 MHz reference -> 25.000 MHz pixel clock
 **                                  -> 125.000 MHz serial clock (10:1)
 **
 **  Derived from the vendor IP-generator output
 **  (board_test: al_ip/pll_hdmi1_4b/pll_hdmi1_4b.v and
 **   src/5640/sdram_ctrl_4p/Sdram_PLL.v, both generated by
 **   Anlogic IP Generator for the very same device EG4S20BG256).
 **  Structure and loop-filter parameters are copied unchanged; only the
 **  output dividers were recalculated.  See docs/research/m0-report.md
 **  for the VCO/divider arithmetic and the phase discussion.
 **
 **  VCO arithmetic (FEEDBK_MODE = NOCOMP, FEEDBK_PATH = VCO_PHASE_0,
 **  i.e. internal feedback, same as Sdram_PLL):
 **      Fvco   = FIN * FBCLK_DIV / REFCLK_DIV = 50 * 20 / 1 = 1000 MHz
 **      CLKCn  = Fvco / CLKCn_DIV
 **      C0 = 1000/10 = 100.000 MHz  (feedback / spare)
 **      C1 = 1000/40 =  25.000 MHz  (pixel clock)
 **      C2 = 1000/ 8 = 125.000 MHz  (serial clock)
 **  CLKCn_CPHASE = DIV-1 is the "no coarse phase shift" value used by the
 **  generator for every 0-degree output.  CLKC2_FPHASE = 7 is the largest
 **  legal fine phase (0..7); one step is VCO period/8 = 0.125 ns, so the
 **  serial clock leads/lags by 0.875 ns (-> ~39 deg of the 8 ns period,
 **  90 deg would need FPHASE = 16 which does not exist).
 \************************************************************/
`timescale 1 ns / 100 fs

module pll_m4_hdmi (
    refclk,
    reset,
    extlock,
    clk0_out,
    clk1_out,
    clk2_out
);

    input  wire refclk;     // 50 MHz
    input  wire reset;      // unused (tied to 1'b0 by the top level)
    output wire extlock;    // PLL lock, high = locked
    output wire clk0_out;   // 100.000 MHz (unused, feedback tap)
    output wire clk1_out;   //  25.000 MHz pixel clock
    output wire clk2_out;   // 125.000 MHz serial clock

    wire S_unused_c3;
    wire S_unused_c4;
    wire S_unused_psdone;
    wire [7:0] S_unused_do;

    EG_PHY_PLL #(
        .DPHASE_SOURCE      ("DISABLE"),
        .DYNCFG             ("DISABLE"),
        .FIN                ("50.000000"),
        .FEEDBK_MODE        ("NOCOMP"),
        .FEEDBK_PATH        ("VCO_PHASE_0"),
        .STDBY_ENABLE       ("DISABLE"),
        .PLLRST_ENA         ("ENABLE"),
        .SYNC_ENABLE        ("DISABLE"),
        .GMC_GAIN           (4),
        .ICP_CURRENT        (13),
        .KVCO               (4),
        .LPF_CAPACITOR      (1),
        .LPF_RESISTOR       (4),
        .REFCLK_DIV         (1),
        .FBCLK_DIV          (20),
        .CLKC0_ENABLE       ("ENABLE"),
        .CLKC0_DIV          (10),
        .CLKC0_CPHASE       (9),
        .CLKC0_FPHASE       (0),
        .CLKC1_ENABLE       ("ENABLE"),
        .CLKC1_DIV          (40),
        .CLKC1_CPHASE       (39),
        .CLKC1_FPHASE       (0),
        .CLKC2_ENABLE       ("ENABLE"),
        .CLKC2_DIV          (8),
        .CLKC2_CPHASE       (7),
        .CLKC2_FPHASE       (7)
    ) pll_inst (
        .refclk     (refclk),
        .reset      (reset),
        .stdby      (1'b0),
        .extlock    (extlock),
        .load_reg   (1'b0),
        .psclk      (1'b0),
        .psdown     (1'b0),
        .psstep     (1'b0),
        .psclksel   (3'b000),
        .psdone     (S_unused_psdone),
        .dclk       (1'b0),
        .dcs        (1'b0),
        .dwe        (1'b0),
        .di         (8'b00000000),
        .daddr      (6'b000000),
        .do         (S_unused_do),
        .fbclk      (1'b0),
        .clkc       ({S_unused_c4, S_unused_c3, clk2_out, clk1_out, clk0_out})
    );

endmodule
